<?php
declare(strict_types=1);

/**
 * install_admin_paid_payouts_dashboard_v007_20261117_202500pm.php
 *
 * VERSION: v007
 * LAST MODIFIED: 11/17/2026 8:25 pm ET
 *
 * PURPOSE:
 * - Add Edit controls for payment, payout, and rollover transactions.
 * - Keep rollover-pair edits synchronized.
 * - Prevent expanded team editors from widening the main table/page.
 * - Add persistent expandable bottom reading space.
 * - Preserve all existing financial data.
 *
 * PHP: 7.3 compatible.
 */

date_default_timezone_set('America/New_York');

$root = dirname(__DIR__);
$pageTarget = $root.'/admin_paid_payouts.php';
$helperTarget = $root.'/admin_paid_payouts_helper.php';
$backupRoot = $root.'/_installer_backups';
$stateFile = __DIR__.'/.install_admin_paid_payouts_dashboard_v007_state.json';

$PAGE_B64 = '';
$HELPER_B64 = '';
$PAGE_SHA = '002e3b7912d1aa229de57dc2f3d28843821bfcff0cb5d437dbb431cfcb55b51d';
$HELPER_SHA = '3c96297e8c85037d1abb97f7c3cbac4f68d71013c5d0a95a1fe9536ae60656f1';

function v7_h($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function v7_lint(string $path): array {
    $out = trim((string)@shell_exec('php -l '.escapeshellarg($path).' 2>&1'));
    return [strpos($out, 'No syntax errors detected') !== false, $out];
}
function v7_atomic(string $path, string $content): void {
    $tmp = $path.'.tmp_'.getmypid().'_'.bin2hex(random_bytes(3));
    if (@file_put_contents($tmp, $content, LOCK_EX) === false) {
        throw new RuntimeException('Could not write temporary file for '.basename($path));
    }
    @chmod($tmp, 0644);
    if (!@rename($tmp, $path)) {
        @unlink($tmp);
        throw new RuntimeException('Could not install '.basename($path));
    }
    @chmod($path, 0644);
}
function v7_load(string $path): array {
    if (!is_file($path)) return [];
    $d = json_decode((string)@file_get_contents($path), true);
    return is_array($d) ? $d : [];
}
function v7_save(string $path, array $state): void {
    @file_put_contents($path, json_encode($state, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES));
}

$page = base64_decode($PAGE_B64, true);
$helper = base64_decode($HELPER_B64, true);

$checks = [];
$checks[] = ['Installer running from /public_html/_installers', realpath(__DIR__) === realpath($root.'/_installers'), __DIR__];
$checks[] = ['Current admin page exists', is_file($pageTarget), $pageTarget];
$checks[] = ['Current helper exists', is_file($helperTarget), $helperTarget];
$checks[] = ['Transaction table exists', false, 'mrl_financial_transactions'];

require_once $root.'/config.php';

try {
    $q = $dbo->query("SHOW TABLES LIKE 'mrl_financial_transactions'");
    $checks[3][1] = (bool)$q->fetchColumn();
} catch (Throwable $e) {
    $checks[3][2] = $e->getMessage();
}

$checks[] = ['Embedded v007 page decoded', is_string($page), is_string($page) ? strlen($page).' bytes' : 'decode failed'];
$checks[] = ['Embedded v006 helper decoded', is_string($helper), is_string($helper) ? strlen($helper).' bytes' : 'decode failed'];

foreach ([['page', $page], ['helper', $helper]] as $pair) {
    $tmp = tempnam(sys_get_temp_dir(), 'mrl_v7_');
    @file_put_contents($tmp, $pair[1]);
    list($ok, $detail) = v7_lint($tmp);
    @unlink($tmp);
    $checks[] = ['Candidate '.$pair[0].' php -l', $ok, $detail];
}

$preOk = true;
foreach ($checks as $c) {
    if (!$c[1]) $preOk = false;
}

$message = '';
$state = v7_load($stateFile);

if ((string)($_POST['action'] ?? '') === 'apply' && $preOk) {
    try {
        if (!is_dir($backupRoot) && !@mkdir($backupRoot, 0755, true) && !is_dir($backupRoot)) {
            throw new RuntimeException('Could not create backup root.');
        }

        $backupDir = $backupRoot.'/admin_paid_payouts_dashboard_v007_'.date('Ymd_His');

        if (!@mkdir($backupDir, 0755, true) && !is_dir($backupDir)) {
            throw new RuntimeException('Could not create backup folder.');
        }

        if (!@copy($pageTarget, $backupDir.'/admin_paid_payouts.php')) {
            throw new RuntimeException('Could not back up admin_paid_payouts.php');
        }

        if (!@copy($helperTarget, $backupDir.'/admin_paid_payouts_helper.php')) {
            throw new RuntimeException('Could not back up admin_paid_payouts_helper.php');
        }

        v7_atomic($helperTarget, $helper);
        v7_atomic($pageTarget, $page);

        foreach ([[$pageTarget, $PAGE_SHA], [$helperTarget, $HELPER_SHA]] as $item) {
            list($lintOk, $lintDetail) = v7_lint($item[0]);
            if (!$lintOk) {
                throw new RuntimeException(basename($item[0]).' failed installed php -l: '.$lintDetail);
            }
            if (hash_file('sha256', $item[0]) !== $item[1]) {
                throw new RuntimeException(basename($item[0]).' SHA mismatch after install.');
            }
        }

        $state = [
            'applied' => true,
            'applied_at' => date('c'),
            'backup_dir' => $backupDir,
        ];
        v7_save($stateFile, $state);
        $message = 'PASS — v007 dashboard update installed.';
    } catch (Throwable $e) {
        $message = 'FAIL — '.$e->getMessage();
    }
}

$state = v7_load($stateFile);
$post = [];

if (!empty($state['applied'])) {
    foreach ([[$pageTarget, $PAGE_SHA, 'admin_paid_payouts.php'], [$helperTarget, $HELPER_SHA, 'admin_paid_payouts_helper.php']] as $item) {
        $exists = is_file($item[0]);
        $post[] = [$item[2].' exists', $exists, $item[0]];
        if ($exists) {
            list($lintOk, $lintDetail) = v7_lint($item[0]);
            $post[] = [$item[2].' php -l', $lintOk, $lintDetail];
            $post[] = [$item[2].' SHA matches', hash_file('sha256', $item[0]) === $item[1], hash_file('sha256', $item[0])];
        }
    }
}
